function relayPick(mode){
  /* FIX: دکمهٔ «تصادفی» قبلاً به شاخهٔ else میافتاد و رلهها را خاموش میکرد. */
  if(mode==='random'){
    var pool=RIX.relayPool||[];
    if(pool.length){
      var pick=pool[Math.floor(Math.random()*pool.length)];
      var ep=(pick.endpoint||(pick.ip+':'+(pick.port||443)));
      RIX.s.proxyIP=ep;RIX.s.proxyRelays=[ep];RIX.s.proxyEnabled=true;
    }else{RIX.s.proxyIP='';RIX.s.proxyRelays=[];RIX.s.proxyEnabled=true;}
  } else if(mode==='auto'){
    RIX.s.proxyIP='';RIX.s.proxyRelays=[];RIX.s.proxyEnabled=true;
  } else {
    RIX.s.proxyIP='';RIX.s.proxyRelays=[];RIX.s.proxyEnabled=false;
  }
  var f=document.getElementById('s-proxyip');if(f)f.value=RIX.s.proxyIP;
  var en=document.getElementById('s-proxyon');if(en)en.checked=RIX.s.proxyEnabled;
  renderRelays();
  saveSettings();
  toast(mode==='none'?'رلهها خاموش شد':(mode==='random'?'رلهٔ تصادفی انتخاب شد ✓':'حالت خودکار ✓'),true);
}
